export function init(tickets:readonly Ticket[]):State{return {tickets:tickets.map(ticket=>({...ticket})),pending:[],hidden:new Set<number>(),error:null};}
export function visibleTickets(state:State):Ticket[]{const ids=new Set(state.pending.map(operation=>operation.id));return state.tickets.filter(ticket=>!ids.has(ticket.id));}
