type TimerRecord={token:number;id:number;remaining:number;deadline:number;timer:ReturnType<typeof setTimeout>|null;reasons:Set<"hover"|"focus">;commit:()=>void};const browserNow=()=>performance.now();
export function UndoTickets({initialTickets,onCommit,clock=browserNow}:{initialTickets:readonly Ticket[];onCommit:(id:number)=>void;clock?:()=>number}){const [state,dispatch]=useReducer(reducer,initialTickets,init);const timers=useRef(new Map<number,TimerRecord>());const nextToken=useRef(1);useEffect(()=>()=>{for(const record of timers.current.values())if(record.timer!==null)clearTimeout(record.timer);timers.current.clear();},[]);function finish(record:TimerRecord){if(timers.current.get(record.token)!==record)return;timers.current.delete(record.token);record.timer=null;try{record.commit();dispatch({type:"confirmed",token:record.token});}catch{dispatch({type:"failed",token:record.token});}}function schedule(record:TimerRecord){record.deadline=clock()+record.remaining;record.timer=setTimeout(()=>finish(record),record.remaining);}function remove(id:number){if(!state.tickets.some(ticket=>ticket.id===id)||[...timers.current.values()].some(record=>record.id===id))return;if(!Number.isSafeInteger(nextToken.current))throw RangeError("Token");const token=nextToken.current++;const record:TimerRecord={token,id,remaining:5000,deadline:0,timer:null,reasons:new Set(),commit:()=>onCommit(id)};timers.current.set(token,record);dispatch({type:"removed",id,token});schedule(record);}function undo(token:number){const record=timers.current.get(token);if(!record)return;if(record.timer!==null)clearTimeout(record.timer);timers.current.delete(token);dispatch({type:"undone",token});}function pause(token:number,reason:"hover"|"focus"){const record=timers.current.get(token);if(!record||record.reasons.has(reason))return;if(record.reasons.size===0){record.remaining=Math.max(0,record.deadline-clock());if(record.timer!==null)clearTimeout(record.timer);record.timer=null;}record.reasons.add(reason);dispatch({type:"paused",token,paused:true});}function resume(token:number,reason:"hover"|"focus"){const record=timers.current.get(token);if(!record)return;record.reasons.delete(reason);if(record.reasons.size===0&&record.timer===null){dispatch({type:"paused",token,paused:false});schedule(record);}}const visible=visibleTickets(state);return <main><h1>Usuwanie z cofnięciem</h1><p>Przykład lokalny: finalizacja po 5 sekundach, pauza podczas hover lub fokusu toastu. Zamknięcie samego toastu nie anuluje operacji.</p><ul>{visible.map(ticket=><li key={ticket.id}>{ticket.title}<button type="button" onClick={()=>remove(ticket.id)}>Usuń #{ticket.id}</button></li>)}</ul><section aria-label="Oczekujące operacje"><h2>Oczekujące operacje</h2><ul>{state.pending.map(operation=><li key={operation.token} onFocusCapture={()=>pause(operation.token,"focus")} onBlurCapture={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node|null))resume(operation.token,"focus");}}>Ticket #{operation.id}<button type="button" onClick={()=>undo(operation.token)}>Cofnij usunięcie #{operation.id}</button></li>)}</ul></section><section className="toasts" aria-label="Powiadomienia" aria-live="polite">{visibleToasts(state).map(operation=><div key={operation.token} className="toast" onMouseEnter={()=>pause(operation.token,"hover")} onMouseLeave={()=>resume(operation.token,"hover")} onFocusCapture={()=>pause(operation.token,"focus")} onBlurCapture={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node|null))resume(operation.token,"focus");}}>Usunięto ticket #{operation.id}{operation.paused&&<span> — odliczanie wstrzymane</span>}<button type="button" onClick={()=>undo(operation.token)}>Cofnij</button><button type="button" aria-label={"Ukryj powiadomienie #"+operation.id} onClick={()=>{resume(operation.token,"hover");resume(operation.token,"focus");dispatch({type:"hidden",token:operation.token});}}>×</button></div>)}</section>{state.error&&<section role="alert"><p>{state.error}</p><button type="button" onClick={()=>dispatch({type:"errorDismissed"})}>Zamknij błąd</button></section>}</main>;}

