e===0&&record.timer===null){dispatch({type:"paused",token,paused:false});schedule(record);}}const visible=visibleTickets(state);return <main><h1>Usuwanie z cofnięciem</h1><p>Przykład lokalny: finalizacja po 5 sekundach, pauza podczas hover lub fokusu toastu. Zamknięcie samego toastu nie anuluje operacji.</p><ul>{visible.map(ticket=><li key={ticket.id}>{ticket.title}<button type="button" onClick={()=>remove(ticket.id)}>Usuń #{ticket.id}</button></li>)}</ul><section aria-label="Oczekujące operacje"><h2>Oczekujące operacje</h2><ul>{state.pending.map(operation=><li key={operation.token} onFocusCapture={()=>pause(operation.token,"focus")} onBlurCapture={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node|null))resume(operation.token,"focus");}}>Ticket #{operation.id}<button type="button" onClick={()=>undo(operation.token)}>Cofnij usunięcie #{operation.id}</button></li>)}</ul></section><section className="toasts" aria-label="Powiadomienia" aria-live="polite">{visibleToasts(state).map(operation=><div key={operation.token} className="toast" onMouseEnter={()=>pause(operation.token,"hover")} onMouseLeave={()=>resume(operation.token,"hover")} onFocusCapture={()=>pause(operation.token,"focus")} onBlurCapture={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node|null))resume(operation.token,"focus");}}>Usunięto ticket #{operation.id}{operation.paused&&<span> — odliczanie wstrzymane</span>}<button type="button" onClick={()=>undo(operation.token)}>Cofnij</button><button type="button" aria-label={"Ukryj powiadomienie #"+operation.id} onClick={()=>{resume(operation.token,"hover");resume(operation.token,"focus");dispatch({type:"hidden",token:operation.token});}}>×</button></div>)}</section>{state.error&&<section role="alert"><p>{state.error}</p><button type="button" onClick={()=>dispatch({type:"errorDismissed"})}>Zamknij błąd</button></section>}</main>;}

