export function visibleTickets(state:State):Ticket[]{const ids=new Set(state.pending.map(operation=>operation.id));return state.tickets.filter(ticket=>!ids.has(ticket.id));}
export function visibleToasts(state:State):Pending[]{const eligible=state.pending.filter(operation=>!state.hidden.has(operation.token));const protectedItems=eligible.filter(operation=>operation.paused).slice(-3);const slots=3-protectedItems.length;const others=slots>0?eligible.filter(operation=>!operation.paused).slice(-slots):[];const tokens=new Set([...protectedItems,...others].map(operation=>operation.token));return eligible.filter(operation=>tokens.has(operation.token));}
export function reducer(state:State,action:Action):State{switch(action.type){case "removed":if(!state.tickets.some(ticket=>ticket.id===action.id)||state.pending.some(operation=>operation.id===action.id))return state;return {...state,pending:[...state.pending,{id:action.id,token:action.token,paused:false}]};case "undone":case "confirmed":case "failed":{const operation=state.pending.find(item=>item.token===action.token);if(!operation)return state;const hidden=new Set(state.hidden);hidden.delete(action.token);return {...state,tickets:action.type==="confirmed"?state.tickets.filter(ticket=>ticket.id!==operation.id):state.tickets,pending:state.pending.filter(item=>item.token!==action.token),hidden,error:action.type==="failed"?"Usunięcie nie powiodło się; ticket przywrócono.":state.error};}case "hidden":{if(!state.pending.some(item=>item.token===action.token))return state;const hidden=new Set(state.hidden);hidden.add(action.token);return {...state,hidden};}case "paused":return {...state,pending:state.pending.map(item=>item.token===action.token?{...item,paused:action.paused}:item)};case "errorDismissed":return {...state,error:null};default:{const exhaustive:never=action;throw Error(JSON.stringify(exhaustive));}}}
